window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-358b66d9651aa53f"]={"versions": [{"id": "FIG-358b66d9651aa53f", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR-Softwarekomponenten-Architektur (AUTOSAR_SoftwareComponentTemplate). Das Diagramm veranschaulicht die Einbettung des <code>ComplexDeviceDriverComponentType</code> in das AUTOSAR-Typensystem sowie dessen metamodellbasierte Referenzen auf Hardware-Ressourcen und Basissoftware-Beschreibungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Klassen und deren Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>Components::ComplexDeviceDriverComponentType</code>: Spezialisierung bzw. Ausprägung von <code>AtomicSoftwareComponentType</code>.\n</li><li><code>ECUResourceTemplate::HWElement</code>: Repräsentiert als <code>ARElement</code> eine Hardware-Ressource mit dem Attribut <code>+ standbyCurrent: Float [0..1]</code>.\n</li><li><code>BswOverview::BswModuleDescription</code>: Repräsentiert als <code>ARElement</code> mit dem Stereotyp <code>«atpStructureElement»</code> die Beschreibung eines Basissoftware-Moduls mit dem Attribut <code>+ moduleId: Int</code>.\n</li></ul>\n<p class=\"fig-p\">Assoziationen:</p>\n<ul class=\"fig-list\"><li>Unidirektionale Assoziation von <code>ComplexDeviceDriverComponentType</code> zu <code>HWElement</code> mit Rollenname <code>+hardwareElement</code> und Multiplizität <code>0..*</code>.\n</li><li>Unidirektionale Assoziation von <code>ComplexDeviceDriverComponentType</code> zu <code>BswModuleDescription</code> mit Rollenname <code>+bswModuleDescription</code> und Multiplizität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Beziehungen definieren deklarative Referenzen zur Entwurfs- und Konfigurationszeit, über die ein komplexer Gerätetreiber (CDD) mit den von ihm gesteuerten Hardware-Elementen und den korrespondierenden BSW-Modulbeschreibungen verknüpft wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>ComplexDeviceDriverComponentType</code> kann optional mehrere Hardware-Elemente (<code>0..*</code>) und BSW-Modulbeschreibungen (<code>0..*</code>) referenzieren. Dies ermöglicht es CDDs, sowohl auf hardwarenahe Eigenschaften der ECU-Ressourcenbeschreibung als auch auf BSW-Modulstrukturen zuzugreifen. <code>moduleId</code> ist als primitiver Typ <code>Int</code> typisiert, während der Ruhestrom <code>standbyCurrent</code> optional als <code>Float [0..1]</code> modelliert ist.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-eadf7a5f8c9c8c36", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR-Softwarekomponenten-Architektur (AUTOSAR_SoftwareComponentTemplate). Das Diagramm veranschaulicht die Einbettung des <code>ComplexDeviceDriverComponentType</code> in das AUTOSAR-Typensystem sowie dessen metamodellbasierte Referenzen auf Hardware-Ressourcen und Basissoftware-Beschreibungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Klassen und deren Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>Components::ComplexDeviceDriverComponentType</code>: Spezialisierung bzw. Ausprägung von <code>AtomicSoftwareComponentType</code>.\n</li><li><code>ECUResourceTemplate::HWElement</code>: Repräsentiert als <code>ARElement</code> eine Hardware-Ressource mit dem Attribut <code>+ standbyCurrent: Float [0..1]</code>.\n</li><li><code>BswOverview::BswModuleDescription</code>: Repräsentiert als <code>ARElement</code> mit dem Stereotyp <code>«atpStructureElement»</code> die Beschreibung eines Basissoftware-Moduls mit dem Attribut <code>+ moduleId: Int</code>.\n</li></ul>\n<p class=\"fig-p\">Assoziationen:</p>\n<ul class=\"fig-list\"><li>Unidirektionale Assoziation von <code>ComplexDeviceDriverComponentType</code> zu <code>HWElement</code> mit Rollenname <code>+hardwareElement</code> und Multiplizität <code>0..*</code>.\n</li><li>Unidirektionale Assoziation von <code>ComplexDeviceDriverComponentType</code> zu <code>BswModuleDescription</code> mit Rollenname <code>+bswModuleDescription</code> und Multiplizität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Beziehungen definieren deklarative Referenzen zur Entwurfs- und Konfigurationszeit, über die ein komplexer Gerätetreiber (CDD) mit den von ihm gesteuerten Hardware-Elementen und den korrespondierenden BSW-Modulbeschreibungen verknüpft wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>ComplexDeviceDriverComponentType</code> kann optional mehrere Hardware-Elemente (<code>0..*</code>) und BSW-Modulbeschreibungen (<code>0..*</code>) referenzieren. Dies ermöglicht es CDDs, sowohl auf hardwarenahe Eigenschaften der ECU-Ressourcenbeschreibung als auch auf BSW-Modulstrukturen zuzugreifen. <code>moduleId</code> ist als primitiver Typ <code>Int</code> typisiert, während der Ruhestrom <code>standbyCurrent</code> optional als <code>Float [0..1]</code> modelliert ist.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-43eedf967b64bf0e", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR-Softwarekomponenten-Architektur (AUTOSAR_SoftwareComponentTemplate). Das Diagramm veranschaulicht die Einbettung des <code>ComplexDeviceDriverComponentType</code> in das AUTOSAR-Typensystem sowie dessen metamodellbasierte Referenzen auf Hardware-Ressourcen und Basissoftware-Beschreibungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Klassen und deren Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>Components::ComplexDeviceDriverComponentType</code>: Spezialisierung bzw. Ausprägung von <code>AtomicSoftwareComponentType</code>.\n</li><li><code>ECUResourceTemplate::HWElement</code>: Repräsentiert als <code>ARElement</code> eine Hardware-Ressource mit dem Attribut <code>+ standbyCurrent :Float [0..1]</code>.\n</li><li><code>BswOverview::BswModuleDescription</code>: Repräsentiert als <code>ARElement</code> mit dem Stereotyp <code>«atpStructureElement»</code> die Beschreibung eines Basissoftware-Moduls mit dem Attribut <code>+ moduleId :Integer</code>.\n</li></ul>\n<p class=\"fig-p\">Assoziationen:</p>\n<ul class=\"fig-list\"><li>Unidirektionale Assoziation von <code>ComplexDeviceDriverComponentType</code> zu <code>HWElement</code> mit Rollenname <code>+hardwareElement</code> und Multiplizität <code>0..*</code>.\n</li><li>Unidirektionale Assoziation von <code>ComplexDeviceDriverComponentType</code> zu <code>BswModuleDescription</code> mit Rollenname <code>+bswModuleDescription</code> und Multiplizität <code>0..*</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Zustandsübergänge. Die Beziehungen definieren deklarative Referenzen zur Entwurfs- und Konfigurationszeit, über die ein komplexer Gerätetreiber (CDD) mit den von ihm gesteuerten Hardware-Elementen und den korrespondierenden BSW-Modulbeschreibungen verknüpft wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>ComplexDeviceDriverComponentType</code> kann optional mehrere Hardware-Elemente (<code>0..*</code>) und BSW-Modulbeschreibungen (<code>0..*</code>) referenzieren. Dies ermöglicht es CDDs, sowohl auf hardwarenahe Eigenschaften der ECU-Ressourcenbeschreibung als auch auf BSW-Modulstrukturen zuzugreifen. <code>moduleId</code> ist als primitiver Metamodelltyp <code>Integer</code> typisiert, während der Ruhestrom <code>standbyCurrent</code> optional als <code>:Float [0..1]</code> modelliert ist.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-358b66d9651aa53f", "to": "FIG-eadf7a5f8c9c8c36", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-eadf7a5f8c9c8c36", "to": "FIG-43eedf967b64bf0e", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Attribut <code>moduleId</code> der Klasse <code>BswOverview::BswModuleDescription</code>: Datentyp von <code>Int</code> auf <code>Integer</code> geändert.\n</li><li>Attribut <code>standbyCurrent</code> der Klasse <code>ECUResourceTemplate::HWElement</code>: Schreibweise mit vorangestelltem Leerzeichen vor dem Doppelpunkt formatiert (<code>:Float</code>).\n</li></ul>"}]};
